<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
start_app_session();$pdo=app_db();
$adminId=(string)($_SESSION['platform_admin_id']??'');$adminStmt=$pdo->prepare('SELECT id,name,email FROM platform_admins WHERE id=?');$adminStmt->execute([$adminId]);$admin=$adminStmt->fetch();
if(!$admin){unset($_SESSION['platform_admin_id']);header('Location: platform-admin-login.php');exit;}
if(empty($_SESSION['platform_csrf']))$_SESSION['platform_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['platform_csrf'];$flash='';$error='';
if(isset($_GET['logout'])){unset($_SESSION['platform_admin_id']);header('Location: platform-admin-login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Sessão expirada. Atualize a página.');}
    $action=(string)($_POST['action']??'');
    if($action==='subscription'){
        $tenantId=(string)($_POST['tenant_id']??'');$plan=(string)($_POST['plan_code']??'');$status=(string)($_POST['status']??'');$period=trim((string)($_POST['period_end']??''));$notes=trim((string)($_POST['notes']??''));
        $check=$pdo->prepare('SELECT s.plan_code,s.status,s.current_period_end,s.notes,t.name FROM subscriptions s JOIN tenants t ON t.id=s.tenant_id WHERE s.tenant_id=?');$check->execute([$tenantId]);$before=$check->fetch();$validPlan=$pdo->prepare('SELECT 1 FROM subscription_plans WHERE code=? AND active=1');$validPlan->execute([$plan]);
        if(!$before||!$validPlan->fetchColumn()||!in_array($status,['trial','active','past_due','canceled'],true)||($period!==''&&!DateTimeImmutable::createFromFormat('Y-m-d',$period))||strlen($notes)>1000)$error='Confira o plano, o status, a data e as observações.';
        else{$pdo->beginTransaction();try{$pdo->prepare('UPDATE subscriptions SET plan_code=?,status=?,current_period_end=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=?')->execute([$plan,$status,$period!==''?$period:null,$notes,$tenantId]);$details=json_encode(['workspace'=>$before['name'],'before'=>['plan'=>$before['plan_code'],'status'=>$before['status'],'period_end'=>$before['current_period_end']],'after'=>['plan'=>$plan,'status'=>$status,'period_end'=>$period?:null]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$pdo->prepare('INSERT INTO subscription_events(id,tenant_id,admin_id,event_type,details) VALUES(?,?,? ,?,?)')->execute([new_id('evt'),$tenantId,$adminId,'subscription.updated',$details]);$pdo->commit();$flash='Assinatura atualizada.';}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error='Não foi possível salvar a assinatura.';}}
    }elseif($action==='plan'){
        $code=(string)($_POST['code']??'');$name=trim((string)($_POST['name']??''));$price=filter_var($_POST['monthly_price']??'',FILTER_VALIDATE_FLOAT);$active=isset($_POST['active'])?1:0;
        if($name===''||strlen($name)>50||$price===false||$price<0||$price>1000000)$error='Informe um nome válido e um preço mensal entre R$ 0 e R$ 1.000.000.';
        else{$pdo->prepare('UPDATE subscription_plans SET name=?,monthly_price_cents=?,active=? WHERE code=?')->execute([$name,(int)round($price*100),$active,$code]);$flash='Plano atualizado.';}
    }
}
$plans=$pdo->query('SELECT code,name,monthly_price_cents,active FROM subscription_plans ORDER BY monthly_price_cents,code')->fetchAll();
$search=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'all');$allowedFilters=['all','trial','active','past_due','canceled'];if(!in_array($statusFilter,$allowedFilters,true))$statusFilter='all';
$counts=$pdo->query("SELECT COUNT(*) AS total,SUM(status='trial') AS trials,SUM(status='active') AS active,SUM(status='past_due') AS past_due,SUM(status='canceled') AS canceled FROM subscriptions")->fetch();
$sql="SELECT t.id AS tenant_id,t.name AS workspace,t.slug,t.created_at AS registered,s.plan_code,s.status,s.current_period_end,s.notes,p.name AS plan_name,p.monthly_price_cents,u.name AS owner_name,u.email AS owner_email,(SELECT created_at FROM subscription_events e WHERE e.tenant_id=t.id ORDER BY e.created_at DESC LIMIT 1) AS last_change FROM tenants t JOIN subscriptions s ON s.tenant_id=t.id JOIN subscription_plans p ON p.code=s.plan_code LEFT JOIN memberships m ON m.tenant_id=t.id AND m.role='owner' LEFT JOIN users u ON u.id=m.user_id WHERE (?='' OR t.name LIKE ? OR u.email LIKE ?) AND (?='all' OR s.status=?) ORDER BY t.created_at DESC";
$stmt=$pdo->prepare($sql);$like='%'.$search.'%';$stmt->execute([$search,$like,$like,$statusFilter,$statusFilter]);$accounts=$stmt->fetchAll();
function pae($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function money_brl(int $cents):string{return 'R$ '.number_format($cents/100,2,',','.');}
?>
