rand-picture--dark"><source media="(max-width: 640px)" srcset="/brand/affiliey-symbol.png"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></picture><span>ADMINISTRAÇÃO SAAS</span></a><nav class="admin-sidebar-nav" aria-label="Navegação do painel SaaS"><a class="active" href="platform-admin.php">Visão geral</a><a href="#accounts">Clientes e assinaturas</a><a href="#plans">Planos do SaaS</a><a href="login.php">Painel do produtor</a></nav><div class="admin-sidebar-foot">AFFILIEY · CONTROLE DA PLATAFORMA</div></aside><header class="admin-top"><a class="brand" href="platform-admin.php"><picture class="brand-picture brand-picture--dark"><source media="(max-width: 640px)" srcset="/brand/affiliey-symbol.png"><img class="brand-logo" src="/brand/affiliey-logo-dark.png" alt="AFFILIEY"></picture><small class="brand-admin-label">ADMIN</small></a><div class="admin-user"><span><?= pae($admin['name']) ?> · <?= pae($admin['email']) ?></span><a href="platform-admin.php?logout=1">Sair</a></div></header><main class="admin-page"><div class="page-intro"><div><div class="eyebrow">SAAS · CONTROLE DA PLATAFORMA</div><h1>Painel comercial</h1><p>Clientes, planos e situação das assinaturas.</p></div><span class="manual-pill">Gestão manual · gateway não conectado</span></div><?php if($flash): ?><div class="notice success"><?= pae($flash) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= pae($error) ?></div><?php endif; ?>
<section class="metric-grid"><article><span>Espaços clientes</span><b><?= (int)$counts['total'] ?></b></article><article><span>Em período de teste</span><b><?= (int)$counts['trials'] ?></b></article><article><span>Assinaturas ativas</span><b><?= (int)$counts['active'] ?></b></article><article><span>Em atraso</span><b><?= (int)$counts['past_due'] ?></b></article><article><span>Canceladas</span><b><?= (int)$counts['canceled'] ?></b></article></section>
<section class="panel" id="accounts"><div class="panel-heading"><div><h2>Clientes e assinaturas</h2><p>Atualize manualmente o plano, status e data do próximo vencimento.</p></div></div><form class="filters" method="get"><input name="q" value="<?= pae($search) ?>" placeholder="Buscar empresa ou e-mail do proprietário"><select name="status"><option value="all">Todos os status</option><?php foreach(['trial'=>'Teste','active'=>'Ativa','past_due'=>'Em atraso','canceled'=>'Cancelada'] as $key=>$label): ?><option value="<?= $key ?>" <?= $statusFilter===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button class="button" type="submit">Filtrar</button></form>
<div class="account-list"><?php if(!$accounts): ?><p class="empty">Nenhum espaço encontrado.</p><?php endif; ?><?php foreach($accounts as $account): ?><details class="account"><summary><span class="workspace"><b><?= pae($account['workspace']) ?></b><small><?= pae($account['owner_name']??'Proprietário não encontrado') ?> · <?= pae($account['owner_email']??'') ?></small></span><span class="plan-name"><?= pae($account['plan_name']) ?><small><?= money_brl((int)$account['monthly_price_cents']) ?>/mês</small></span><span class="status <?= pae($account['status']) ?>"><?= ['trial'=>'Teste','active'=>'Ativa','past_due'=>'Em atraso','canceled'=>'Cancelada'][$account['status']] ?></span><span class="date"><?= $account['current_period_end']?'Até '.pae(date('d/m/Y',strtotime($account['current_period_end']))):'Sem vencimento' ?></span><span class="expand">Editar⌄</span></summary><form class="edit-sub" method="post"><input type="hidden" name="csrf" value="<?= pae($csrf) ?>"><input type="hidden" name="action" value="subscription"><input type="hidden" name="tenant_id" value="<?= pae($account['tenant_id']) ?>"><label>Plano<select name="plan_code"><?php foreach($plans as $plan): if(!$plan['active']&&$plan['code']!==$account['plan_code'])continue; ?><option value="<?= pae($plan['code']) ?>" <?= $account['plan_code']===$plan['code']?'selected':'' ?>><?= pae($plan['name']) ?> · <?= money_brl((int)$plan['monthly_price_cents']) ?>/mês<?= $plan['active']?'':' (inativo)' ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach(['trial'=>'Período de teste','active'=>'Ativa','past_due'=>'Em atraso','canceled'=>'Cancelada'] as $key=>$label): ?><option value="<?= $key ?>" <?= $account['status']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Próximo vencimento<input type="date" name="period_end" value="<?= pae($account['current_period_end']) ?>"></label><label class="wide">Observações internas<textarea name="notes" maxlength="1000" rows="2" placeholder="Ex.: pagamento confirmado fora da plataforma"><?= pae($account['notes']) ?></textarea></label><button class="button primary" type="submit">Salvar assinatura</button></form></details><?php endforeach; ?></div></section>
<section class="panel plans" id="plans"><div class="panel-heading"><div><h2>Planos do SaaS</h2><p>Os preços aqui são apenas cadastro manual. Ainda não há cobrança automática.</p></div></div><div class="plans-grid"><?php foreach($plans as $plan): ?><form class="plan-card" method="post"><input type="hidden" name="csrf" value="<?= pae($csrf) ?>"><input type="hidden" name="action" value="plan"><input type="hidden" name="code" value="<?= pae($plan['code']) ?>"><label>Nome do plano<input name="name" maxlength="50" value="<?= pae($plan['name']) ?>" required></label><label>Preço mensal (R$)<input name="monthly_price" type="number" min="0" max="1000000" step="0.01" value="<?= number_format((int)$plan['monthly_price_cents']/100,2,'.','') ?>" required></label><label class="check"><input type="checkbox" name="active" value="1" <?= $plan['active']?'checked':'' ?>> Disponível para novas assinaturas</label><button class="button" type="submit">Salvar plano</button></form><?php endforeach; ?></div></section><p class="footnote">Este painel registra alterações administrativas localmente. Para produção, conecte um gateway de pagamentos e implemente webhooks para sincronizar cobranças, renovações e cancelamentos.</p></main></body></html>
